package com.hospital.dao;
import com.hospital.util.DBConnection;import java.sql.*;import java.math.BigDecimal;import java.util.*;
public class DoctorDAO {
 public long create(String name,String specialty,long dept,String phone,BigDecimal fee)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO doctors(full_name,specialization,department_id,phone,consultation_fee) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,specialty);p.setLong(3,dept);p.setString(4,phone);p.setBigDecimal(5,fee);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();return r.getLong(1);}}}
 public List<String> list(String filter)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT d.doctor_id,d.full_name,d.specialization,dp.name,d.phone,d.consultation_fee,d.active FROM doctors d JOIN departments dp USING(department_id) WHERE d.full_name LIKE ? OR d.specialization LIKE ? ORDER BY d.full_name")){p.setString(1,"%"+filter+"%");p.setString(2,"%"+filter+"%");try(ResultSet r=p.executeQuery()){List<String> out=new ArrayList<>();while(r.next())out.add(String.format("%d | %s | %s | %s | %s | fee %s | active=%s",r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getBoolean(7)));return out;}}}
 public void setActive(long id,boolean active)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE doctors SET active=? WHERE doctor_id=?")){p.setBoolean(1,active);p.setLong(2,id);if(p.executeUpdate()==0)throw new SQLException("Doctor not found.");}}
 public void setAvailability(long id,int weekday,Time start,Time end,int slot)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO doctor_availability(doctor_id,day_of_week,start_time,end_time,slot_minutes) VALUES(?,?,?,?,?)")){p.setLong(1,id);p.setInt(2,weekday);p.setTime(3,start);p.setTime(4,end);p.setInt(5,slot);p.executeUpdate();}}
}
